#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Hover<'a> {
    pub serial: Serial,
    pub proto: EntityId,
    pub status: Status,
    /// the entity's items summed per key, in key order
    pub contents: List<'a, ItemCount>,
}

impl<'a> Hover<'a> {
    /// The bytes before the first variable-length field.
    pub const PREFIX: usize = 8;
    pub const OFFSET_SERIAL: usize = 0;
    pub const OFFSET_PROTO: usize = 4;
    pub const OFFSET_STATUS: usize = 6;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}serial"), i128::from(self.serial.0));
        d.int(&format!("{prefix}proto"), i128::from(self.proto.0));
        d.int(&format!("{prefix}status"), i128::from(self.status.value()));
        d.int(&format!("{}.len", &format!("{prefix}contents")), self.contents.len() as i128);
        for (i, x) in self.contents.iter().enumerate() {
            x.dump(d, &format!("{}.", &format!("{}[{i}]", &format!("{prefix}contents"))));
        }
    }

    /// Decodes one value that fills `bytes` exactly.
    pub fn decode_exact(bytes: &'a [u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let v = Self::decode(&mut r)?;
        r.finish("Hover")?;
        Ok(v)
    }
}

impl Default for Hover<'_> {
    fn default() -> Self {
        Self {
            serial: Serial::default(),
            proto: EntityId::default(),
            status: Status::default(),
            contents: List::default(),
        }
    }
}

impl<'a> Packed<'a> for Hover<'a> {
    fn decode(r: &mut Reader<'a>) -> DResult<Self> {
        let f_serial = Serial::read(r, "Hover.serial")?;
        let f_proto = EntityId::read(r, "Hover.proto")?;
        let f_status = Status::read(r, "Hover.status")?;
        r.zeros(1, "Hover.reserved")?;
        let f_contents = List::read_counted(r, 2, 64, "Hover.contents")?;

        Ok(Self { serial: f_serial, proto: f_proto, status: f_status, contents: f_contents })
    }
    fn encode(&self, w: &mut Writer<'_>) -> EResult {
        self.serial.write(w, "Hover.serial")?;
        self.proto.write(w, "Hover.proto")?;
        self.status.write(w, "Hover.status")?;
        w.zeros(1);
        w.count(self.contents.len(), 2, 64, "Hover.contents")?;
        self.contents.write(w, "Hover.contents")?;

        Ok(())
    }
}

