#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(transparent)]
pub struct HudFlags(u8);

impl HudFlags {
    pub const CLOSED: Self = Self(1 << 0);
    pub const VICTORY: Self = Self(1 << 1);
    /// Every declared bit.
    pub const ALL: Self = Self(3);
    /// No bits.
    pub const EMPTY: Self = Self(0);

    pub const fn bits(self) -> u8 {
        self.0
    }
    /// The flags with these bits, if every bit is declared.
    pub const fn from_bits(v: u8) -> Option<Self> {
        if v & !Self::ALL.0 == 0 { Some(Self(v)) } else { None }
    }
    /// The flags with these bits, declared or not (tests and fixtures; decoders refuse undeclared bits).
    pub const fn from_bits_retain(v: u8) -> Self {
        Self(v)
    }
    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }
    pub const fn difference(self, other: Self) -> Self {
        Self(self.0 & !other.0)
    }
    /// These flags with `other` set or cleared.
    pub const fn with(self, other: Self, on: bool) -> Self {
        if on { self.union(other) } else { self.difference(other) }
    }
}

impl core::ops::BitOr for HudFlags {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self {
        self.union(rhs)
    }
}

impl Fixed for HudFlags {
    const SIZE: usize = 1;
    fn read(r: &mut Reader<'_>, field: &'static str) -> DResult<Self> {
        let at = r.pos();
        let v = r.u8(field)?;
        Self::from_bits(v).ok_or_else(|| r.err_at(at, ErrorKind::BadFlags, field))
    }
    fn write(&self, w: &mut Writer<'_>, _field: &'static str) -> EResult {
        w.u8(self.0);
        Ok(())
    }
}

