#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct InspectResult<'a> {
    pub serial: Serial,
    pub found: bool,
    pub fields: MsgList<'a, InspectField<'a>>,
}

impl<'a> InspectResult<'a> {
    /// The bytes before the first variable-length field.
    pub const PREFIX: usize = 8;
    pub const OFFSET_SERIAL: usize = 0;
    pub const OFFSET_FOUND: usize = 4;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}serial"), i128::from(self.serial.0));
        d.bool(&format!("{prefix}found"), self.found);
        d.int(&format!("{}.len", &format!("{prefix}fields")), self.fields.len() as i128);
        let mut i = 0usize;
        self.fields.for_each(|x| {
            (*x).dump(d, &format!("{}.", &format!("{}[{i}]", &format!("{prefix}fields"))));
            i += 1;
        });
    }

    /// Decodes one value that fills `bytes` exactly.
    pub fn decode_exact(bytes: &'a [u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let v = Self::decode(&mut r)?;
        r.finish("InspectResult")?;
        Ok(v)
    }
}

impl Default for InspectResult<'_> {
    fn default() -> Self {
        Self { serial: Serial::default(), found: false, fields: MsgList::default() }
    }
}

impl<'a> Packed<'a> for InspectResult<'a> {
    fn decode(r: &mut Reader<'a>) -> DResult<Self> {
        let f_serial = Serial::read(r, "InspectResult.serial")?;
        let f_found = r.bool("InspectResult.found")?;
        r.zeros(1, "InspectResult.reserved")?;
        r.zeros(2, "InspectResult.reserved2")?;
        let f_fields = MsgList::read_counted(r, 2, 256, "InspectResult.fields")?;

        Ok(Self { serial: f_serial, found: f_found, fields: f_fields })
    }
    fn encode(&self, w: &mut Writer<'_>) -> EResult {
        self.serial.write(w, "InspectResult.serial")?;
        w.bool(self.found);
        w.zeros(1);
        w.zeros(2);
        w.count(self.fields.len(), 2, 256, "InspectResult.fields")?;
        self.fields.write(w)?;

        Ok(())
    }
}

