/// Points p_from … p_(from+count−1) of a key's series at the record's precision. `from` is the point's index in the precision's stream since the world began, mod 65,536: a whole series is the last min(300, n) points, an incremental one the points appended since the previous record (§15.5, B1-r1 15)
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct StatSeries<'a> {
    pub key: StatKey,
    pub from: u16,
    pub produced: List<'a, f32>,
    pub consumed: List<'a, f32>,
}

impl<'a> StatSeries<'a> {
    /// The bytes before the first variable-length field.
    pub const PREFIX: usize = 8;
    pub const OFFSET_KEY: usize = 0;
    pub const OFFSET_FROM: usize = 4;
    pub const OFFSET_COUNT: usize = 6;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}key"), i128::from(self.key.0));
        d.int(&format!("{prefix}from"), i128::from(self.from));
        d.int(&format!("{}.len", &format!("{prefix}produced")), self.produced.len() as i128);
        for (i, x) in self.produced.iter().enumerate() {
            d.f32(&format!("{}[{i}]", &format!("{prefix}produced")), x);
        }
        d.int(&format!("{}.len", &format!("{prefix}consumed")), self.consumed.len() as i128);
        for (i, x) in self.consumed.iter().enumerate() {
            d.f32(&format!("{}[{i}]", &format!("{prefix}consumed")), x);
        }
    }

    /// Decodes one value that fills `bytes` exactly.
    pub fn decode_exact(bytes: &'a [u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let v = Self::decode(&mut r)?;
        r.finish("StatSeries")?;
        Ok(v)
    }
}

impl Default for StatSeries<'_> {
    fn default() -> Self {
        Self { key: StatKey::default(), from: 0, produced: List::default(), consumed: List::default() }
    }
}

impl<'a> Packed<'a> for StatSeries<'a> {
    fn decode(r: &mut Reader<'a>) -> DResult<Self> {
        let f_key = StatKey::read(r, "StatSeries.key")?;
        let f_from = r.u16("StatSeries.from")?;
        let at_count = r.pos();
        let f_count = r.u16("StatSeries.count")?;
        if !(0..=300).contains(&f_count) {
            return Err(r.err_at(at_count, ErrorKind::Range, "StatSeries.count"));
        }
        let f_produced = List::read(r, usize::from(f_count), "StatSeries.produced")?;
        let f_consumed = List::read(r, usize::from(f_count), "StatSeries.consumed")?;

        Ok(Self { key: f_key, from: f_from, produced: f_produced, consumed: f_consumed })
    }
    fn encode(&self, w: &mut Writer<'_>) -> EResult {
        let f_count = count_of(self.produced.len(), 300, "StatSeries.count")? as u16;
        if self.consumed.len() != usize::from(f_count) {
            return Err(enc_err(ErrorKind::BadCount, "StatSeries.consumed"));
        }
        self.key.write(w, "StatSeries.key")?;
        w.u16(self.from);
        w.u16(f_count);
        self.produced.write(w, "StatSeries.produced")?;
        self.consumed.write(w, "StatSeries.consumed")?;

        Ok(())
    }
}

/// sim_state_hash's output and the `hash` query's result (§15.8): the full state hash, then each section's (low word first)
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct StateHash<'a> {
    pub hash: u64,
    pub sections: List<'a, SectionHash>,
}

impl<'a> StateHash<'a> {
    /// The bytes before the first variable-length field.
    pub const PREFIX: usize = 12;
    pub const OFFSET_HASH: usize = 0;
    pub const OFFSET_COUNT: usize = 8;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}hash"), i128::from(self.hash));
        d.int(&format!("{}.len", &format!("{prefix}sections")), self.sections.len() as i128);
        for (i, x) in self.sections.iter().enumerate() {
            x.dump(d, &format!("{}.", &format!("{}[{i}]", &format!("{prefix}sections"))));
        }
    }

    /// Decodes one value that fills `bytes` exactly.
    pub fn decode_exact(bytes: &'a [u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let v = Self::decode(&mut r)?;
        r.finish("StateHash")?;
        Ok(v)
    }
}

impl Default for StateHash<'_> {
    fn default() -> Self {
        Self { hash: 0, sections: List::default() }
    }
}

impl<'a> Packed<'a> for StateHash<'a> {
    fn decode(r: &mut Reader<'a>) -> DResult<Self> {
        let f_hash = r.u64("StateHash.hash")?;
        let f_count = r.u32("StateHash.count")?;
        let f_sections = List::read(r, f_count as usize, "StateHash.sections")?;

        Ok(Self { hash: f_hash, sections: f_sections })
    }
    fn encode(&self, w: &mut Writer<'_>) -> EResult {
        let f_count = count_of(self.sections.len(), u64::from(u32::MAX), "StateHash.count")? as u32;
        w.u64(self.hash);
        w.u32(f_count);
        self.sections.write(w, "StateHash.sections")?;

        Ok(())
    }
}

#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Stats<'a> {
    pub precision: StatPrecision,
    pub tab: StatTab,
    pub flags: StatsFlags,
    pub entries: List<'a, StatEntry>,
    pub series: MsgList<'a, StatSeries<'a>>,
}

impl<'a> Stats<'a> {
    /// The bytes before the first variable-length field.
    pub const PREFIX: usize = 4;
    pub const OFFSET_PRECISION: usize = 0;
    pub const OFFSET_TAB: usize = 1;
    pub const OFFSET_FLAGS: usize = 2;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}precision"), i128::from(self.precision.value()));
        d.int(&format!("{prefix}tab"), i128::from(self.tab.value()));
        d.int(&format!("{prefix}flags"), i128::from(self.flags.bits()));
        d.int(&format!("{}.len", &format!("{prefix}entries")), self.entries.len() as i128);
        for (i, x) in self.entries.iter().enumerate() {
            x.dump(d, &format!("{}.", &format!("{}[{i}]", &format!("{prefix}entries"))));
        }
        d.int(&format!("{}.len", &format!("{prefix}series")), self.series.len() as i128);
        let mut i = 0usize;
        self.series.for_each(|x| {
            (*x).dump(d, &format!("{}.", &format!("{}[{i}]", &format!("{prefix}series"))));
            i += 1;
        });
    }

    /// Decodes one value that fills `bytes` exactly.
    pub fn decode_exact(bytes: &'a [u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let v = Self::decode(&mut r)?;
        r.finish("Stats")?;
        Ok(v)
    }
}

impl Default for Stats<'_> {
    fn default() -> Self {
        Self {
            precision: StatPrecision::default(),
            tab: StatTab::default(),
            flags: StatsFlags::default(),
            entries: List::default(),
            series: MsgList::default(),
        }
    }
}

impl<'a> Packed<'a> for Stats<'a> {
    fn decode(r: &mut Reader<'a>) -> DResult<Self> {
        let f_precision = StatPrecision::read(r, "Stats.precision")?;
        let f_tab = StatTab::read(r, "Stats.tab")?;
        let f_flags = StatsFlags::read(r, "Stats.flags")?;
        r.zeros(1, "Stats.reserved")?;
        let f_entries = List::read_counted(r, 2, 256, "Stats.entries")?;
        let f_series = MsgList::read_counted(r, 2, 24, "Stats.series")?;

        Ok(Self { precision: f_precision, tab: f_tab, flags: f_flags, entries: f_entries, series: f_series })
    }
    fn encode(&self, w: &mut Writer<'_>) -> EResult {
        self.precision.write(w, "Stats.precision")?;
        self.tab.write(w, "Stats.tab")?;
        self.flags.write(w, "Stats.flags")?;
        w.zeros(1);
        w.count(self.entries.len(), 2, 256, "Stats.entries")?;
        self.entries.write(w, "Stats.entries")?;
        w.count(self.series.len(), 2, 24, "Stats.series")?;
        self.series.write(w)?;

        Ok(())
    }
}

#[derive(Clone, Copy, Debug, Default, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(transparent)]
pub struct StatsFlags(u8);

impl StatsFlags {
    pub const SERIES: Self = Self(1 << 0);
    /// Every declared bit.
    pub const ALL: Self = Self(1);
    /// No bits.
    pub const EMPTY: Self = Self(0);

    pub const fn bits(self) -> u8 {
        self.0
    }
    /// The flags with these bits, if every bit is declared.
    pub const fn from_bits(v: u8) -> Option<Self> {
        if v & !Self::ALL.0 == 0 { Some(Self(v)) } else { None }
    }
    /// The flags with these bits, declared or not (tests and fixtures; decoders refuse undeclared bits).
    pub const fn from_bits_retain(v: u8) -> Self {
        Self(v)
    }
    pub const fn contains(self, other: Self) -> bool {
        self.0 & other.0 == other.0
    }
    pub const fn union(self, other: Self) -> Self {
        Self(self.0 | other.0)
    }
    pub const fn difference(self, other: Self) -> Self {
        Self(self.0 & !other.0)
    }
    /// These flags with `other` set or cleared.
    pub const fn with(self, other: Self, on: bool) -> Self {
        if on { self.union(other) } else { self.difference(other) }
    }
}

impl core::ops::BitOr for StatsFlags {
    type Output = Self;
    fn bitor(self, rhs: Self) -> Self {
        self.union(rhs)
    }
}

impl Fixed for StatsFlags {
    const SIZE: usize = 1;
    fn read(r: &mut Reader<'_>, field: &'static str) -> DResult<Self> {
        let at = r.pos();
        let v = r.u8(field)?;
        Self::from_bits(v).ok_or_else(|| r.err_at(at, ErrorKind::BadFlags, field))
    }
    fn write(&self, w: &mut Writer<'_>, _field: &'static str) -> EResult {
        w.u8(self.0);
        Ok(())
    }
}

