/// A subscription request (§15.5): main → shell → sim_subscribe. Sending an existing sub_id replaces it
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd)]
pub struct SubRequest<'a> {
    pub sub_id: SubId,
    pub kind: ProjectionKind,
    pub flags: SubFlags,
    /// an entity serial, a player index or 0, by kind
    pub target: u32,
    pub p0: u32,
    pub p1: u32,
    pub p2: u32,
    pub p3: u32,
    /// list parameters (STATS: up to 256 u32 StatKeys)
    pub tail: Option<&'a [u8]>,
}

impl<'a> SubRequest<'a> {
    /// The bytes before the first variable-length field.
    pub const PREFIX: usize = 28;
    pub const OFFSET_SUB_ID: usize = 0;
    pub const OFFSET_KIND: usize = 4;
    pub const OFFSET_FLAGS: usize = 6;
    pub const OFFSET_TARGET: usize = 8;
    pub const OFFSET_P0: usize = 12;
    pub const OFFSET_P1: usize = 16;
    pub const OFFSET_P2: usize = 20;
    pub const OFFSET_P3: usize = 24;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}sub_id"), i128::from(self.sub_id.0));
        d.int(&format!("{prefix}kind"), i128::from(self.kind.value()));
        d.int(&format!("{prefix}flags"), i128::from(self.flags.bits()));
        d.int(&format!("{prefix}target"), i128::from(self.target));
        d.int(&format!("{prefix}p0"), i128::from(self.p0));
        d.int(&format!("{prefix}p1"), i128::from(self.p1));
        d.int(&format!("{prefix}p2"), i128::from(self.p2));
        d.int(&format!("{prefix}p3"), i128::from(self.p3));
        if let Some(x) = &self.tail {
            d.bytes(&format!("{prefix}tail"), x);
        }
    }

    /// Decodes one value that fills `bytes` exactly.
    pub fn decode_exact(bytes: &'a [u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let v = Self::decode(&mut r)?;
        r.finish("SubRequest")?;
        Ok(v)
    }
}

impl Default for SubRequest<'_> {
    fn default() -> Self {
        Self {
            sub_id: SubId::default(),
            kind: ProjectionKind::default(),
            flags: SubFlags::default(),
            target: 0,
            p0: 0,
            p1: 0,
            p2: 0,
            p3: 0,
            tail: None,
        }
    }
}

impl<'a> Packed<'a> for SubRequest<'a> {
    fn decode(r: &mut Reader<'a>) -> DResult<Self> {
        let f_sub_id = SubId::read(r, "SubRequest.sub_id")?;
        let f_kind = ProjectionKind::read(r, "SubRequest.kind")?;
        let f_flags = SubFlags::read(r, "SubRequest.flags")?;
        let f_target = r.u32("SubRequest.target")?;
        let f_p0 = r.u32("SubRequest.p0")?;
        let f_p1 = r.u32("SubRequest.p1")?;
        let f_p2 = r.u32("SubRequest.p2")?;
        let f_p3 = r.u32("SubRequest.p3")?;
        let f_tail =
            if f_flags.contains(SubFlags::TAIL) { Some(r.bytes(2, 4096, "SubRequest.tail")?) } else { None };

        Ok(Self {
            sub_id: f_sub_id,
            kind: f_kind,
            flags: f_flags,
            target: f_target,
            p0: f_p0,
            p1: f_p1,
            p2: f_p2,
            p3: f_p3,
            tail: f_tail,
        })
    }
    fn encode(&self, w: &mut Writer<'_>) -> EResult {
        self.sub_id.write(w, "SubRequest.sub_id")?;
        self.kind.write(w, "SubRequest.kind")?;
        self.flags.write(w, "SubRequest.flags")?;
        w.u32(self.target);
        w.u32(self.p0);
        w.u32(self.p1);
        w.u32(self.p2);
        w.u32(self.p3);
        if self.flags.contains(SubFlags::TAIL) != self.tail.is_some() {
            return Err(enc_err(ErrorKind::Inconsistent, "SubRequest.tail"));
        }
        if let Some(x) = self.tail {
            w.len_bytes(x, 2, 4096, "SubRequest.tail")?;
        }

        Ok(())
    }
}

/// Developer reasons without player-facing text (§15.5); the shell logs them. Also the body of a failed query
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]
#[repr(u16)]
pub enum UiInvalidReason {
    Unsupported = 1,
    BadParameters = 2,
    OverLimit = 3,
    NotFound = 4,
}

impl Default for UiInvalidReason {
    fn default() -> Self {
        Self::Unsupported
    }
}

impl UiInvalidReason {
    /// Every value, in declaration order.
    pub const ALL: [Self; 4] = [Self::Unsupported, Self::BadParameters, Self::OverLimit, Self::NotFound];

    /// The value on the wire.
    pub const fn value(self) -> u16 {
        self as u16
    }

    /// The value with this number, if the schema declares one.
    pub const fn from_value(v: u16) -> Option<Self> {
        match v {
            1 => Some(Self::Unsupported),
            2 => Some(Self::BadParameters),
            3 => Some(Self::OverLimit),
            4 => Some(Self::NotFound),
            _ => None,
        }
    }

    /// The schema's name of the value.
    pub const fn name(self) -> &'static str {
        match self {
            Self::Unsupported => "unsupported",
            Self::BadParameters => "bad_parameters",
            Self::OverLimit => "over_limit",
            Self::NotFound => "not_found",
        }
    }

    /// The value with this schema name.
    pub fn from_name(s: &str) -> Option<Self> {
        Self::ALL.iter().copied().find(|v| v.name() == s)
    }
}

impl TryFrom<u16> for UiInvalidReason {
    type Error = u16;
    fn try_from(v: u16) -> Result<Self, u16> {
        Self::from_value(v).ok_or(v)
    }
}

impl Fixed for UiInvalidReason {
    const SIZE: usize = 2;
    fn read(r: &mut Reader<'_>, field: &'static str) -> DResult<Self> {
        let at = r.pos();
        let v = r.u16(field)?;
        Self::from_value(v).ok_or_else(|| r.err_at(at, ErrorKind::BadEnum, field))
    }
    fn write(&self, w: &mut Writer<'_>, _field: &'static str) -> EResult {
        w.u16(self.value());
        Ok(())
    }
}

/// One record of the UI section: the header, the kind's record (`len` bytes; a UiInvalidReason when status is 2), padding to 4
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct UiRecord<'a> {
    pub sub_id: SubId,
    pub kind: ProjectionKind,
    pub status: UiStatus,
    pub version: u32,
    pub body: &'a [u8],
}

impl<'a> UiRecord<'a> {
    /// The bytes before the first variable-length field.
    pub const PREFIX: usize = 16;
    pub const OFFSET_SUB_ID: usize = 0;
    pub const OFFSET_KIND: usize = 4;
    pub const OFFSET_STATUS: usize = 6;
    pub const OFFSET_VERSION: usize = 8;
    pub const OFFSET_LEN: usize = 12;

    /// Appends the text dump of the fields (test/fixtures/codec), each path prefixed by `prefix`.
    pub fn dump(&self, d: &mut Dump, prefix: &str) {
        d.int(&format!("{prefix}sub_id"), i128::from(self.sub_id.0));
        d.int(&format!("{prefix}kind"), i128::from(self.kind.value()));
        d.int(&format!("{prefix}status"), i128::from(self.status.value()));
        d.int(&format!("{prefix}version"), i128::from(self.version));
        d.bytes(&format!("{prefix}body"), self.body);
    }

    /// Decodes one value that fills `bytes` exactly.
    pub fn decode_exact(bytes: &'a [u8]) -> DResult<Self> {
        let mut r = Reader::new(bytes);
        let v = Self::decode(&mut r)?;
        r.finish("UiRecord")?;
        Ok(v)
    }
}

impl Default for UiRecord<'_> {
    fn default() -> Self {
        Self {
            sub_id: SubId::default(),
            kind: ProjectionKind::default(),
            status: UiStatus::default(),
            version: 0,
            body: &[],
        }
    }
}

impl<'a> Packed<'a> for UiRecord<'a> {
    fn decode(r: &mut Reader<'a>) -> DResult<Self> {
        let start = r.pos();
        let f_sub_id = SubId::read(r, "UiRecord.sub_id")?;
        let f_kind = ProjectionKind::read(r, "UiRecord.kind")?;
        let f_status = UiStatus::read(r, "UiRecord.status")?;
        let f_version = r.u32("UiRecord.version")?;
        let f_len = r.u32("UiRecord.len")?;
        let f_body = r.take(f_len as usize, "UiRecord.body")?;
        r.pad(start, 4, "UiRecord.padding")?;
        Ok(Self { sub_id: f_sub_id, kind: f_kind, status: f_status, version: f_version, body: f_body })
    }
    fn encode(&self, w: &mut Writer<'_>) -> EResult {
        let start = w.pos();
        let f_len = count_of(self.body.len(), u64::from(u32::MAX), "UiRecord.len")? as u32;
        self.sub_id.write(w, "UiRecord.sub_id")?;
        self.kind.write(w, "UiRecord.kind")?;
        self.status.write(w, "UiRecord.status")?;
        w.u32(self.version);
        w.u32(f_len);
        w.bytes(self.body);
        w.pad(start, 4);
        Ok(())
    }
}

