/// Subscription and query limits (§15.5).
pub const QUERIES_RUNNING: usize = 4;
pub const QUERY_RESULT_MAX: usize = 1048576;
pub const QUERY_STEP_MS: usize = 2;
pub const RECORD_MAX: usize = 65536;
pub const SLOW_CADENCE_TICKS: usize = 60;
pub const STATS_KEYS: usize = 256;
pub const STATS_SERIES_KEYS: usize = 24;
pub const STATS_SUBSCRIPTIONS: usize = 4;
pub const SUBSCRIPTIONS: usize = 32;
pub const UI_SECTION_MAX: usize = 262144;

/// A projection's cadence (§15.5).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Cadence {
    /// Every packet.
    Every,
    /// On subscribing, then at the first extraction at least SLOW_CADENCE_TICKS after the last evaluation.
    Slow,
}

/// What a subscription's `target` holds.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Target {
    None,
    Entity,
    Player,
}

impl ProjectionKind {
    pub const fn cadence(self) -> Cadence {
        match self {
            Self::Hud => Cadence::Slow,
            Self::Character => Cadence::Every,
            Self::Inventory => Cadence::Every,
            Self::EntityPanel => Cadence::Every,
            Self::Hover => Cadence::Every,
            Self::Research => Cadence::Slow,
            Self::Stats => Cadence::Slow,
            Self::Electric => Cadence::Slow,
            Self::World => Cadence::Slow,
            Self::Debug => Cadence::Every,
        }
    }

    pub const fn target(self) -> Target {
        match self {
            Self::Hud => Target::None,
            Self::Character => Target::Player,
            Self::Inventory => Target::Entity,
            Self::EntityPanel => Target::Entity,
            Self::Hover => Target::Entity,
            Self::Research => Target::None,
            Self::Stats => Target::None,
            Self::Electric => Target::Entity,
            Self::World => Target::None,
            Self::Debug => Target::None,
        }
    }

    /// Whether the schema declares the kind's record (the others arrive with later milestones).
    pub const fn has_record(self) -> bool {
        matches!(
            self,
            Self::Hud
                | Self::Character
                | Self::Inventory
                | Self::EntityPanel
                | Self::Hover
                | Self::Stats
                | Self::Debug
        )
    }
}

impl QueryKind {
    /// Dev-build queries (§15.5).
    pub const fn is_dev(self) -> bool {
        matches!(self, Self::Inspect | Self::Hash | Self::Digest)
    }
}

/// Writes one UI record (§15.5): the 16-byte header, the body that `body` writes, padding to 4.
pub fn write_ui_record(
    w: &mut Writer<'_>,
    sub_id: u32,
    kind: ProjectionKind,
    status: UiStatus,
    version: u32,
    body: impl FnOnce(&mut Writer<'_>) -> EResult,
) -> EResult {
    let start = w.pos();
    w.u32(sub_id);
    w.u16(kind.value());
    w.u16(status.value());
    w.u32(version);
    let len_at = w.pos();
    w.u32(0);
    body(w)?;
    let len = w.pos() - len_at - 4;
    if len > RECORD_MAX {
        return Err(enc_err(ErrorKind::TooLong, "UiRecord.body"));
    }
    w.patch_u32(len_at, len as u32);
    w.pad(start, 4);
    Ok(())
}
